SELECT l.lot_id, l.material_code, m.display_name AS material_name, l.work_order_number, l.line_code, q.quality_id, COALESCE(q.defect_code, '') AS defect_code, COALESCE(q.result, '') AS quality_result FROM mes_genealogy_lot l JOIN mes_genealogy_material m ON m.material_code = l.material_code LEFT JOIN mes_genealogy_quality q ON q.lot_id = l.lot_id WHERE l.lot_id = ? ORDER BY q.quality_id
